// Использование:  bun collect.js [минуты] [out.json]
const BASE = process.env.SCREENPIPE_LOCAL_API_URL || "http://localhost:3030";
const WINDOW_MIN = parseInt(process.argv[2] || "60", 10);
const OUT = process.argv[3] || "data.json";

async function sql(query) {
  const r = await fetch(`${BASE}/raw_sql`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ query }),
  });
  if (!r.ok) throw new Error(`raw_sql ${r.status}: ${await r.text()}`);
  const j = await r.json();
  return j?.data ?? [];
}

async function health() {
  try {
    const r = await fetch(`${BASE}/health`);
    return r.ok ? await r.json() : null;
  } catch {
    return null;
  }
}

// Домены/URL достаём из текста кадров: колонка browser_url в hybrid-хранилище пустая.
const URL_RE = /\b((?:https?:\/\/)?(?:[\w-]+\.)+[a-zа-я]{2,}(?:\/[^\s"'<>]*)?)/giu;
const NOISE = /\.(png|jpe?g|gif|svg|webp|css|js|json|xml|woff2?|ttf|eot|ico|mp4|mp3|wav|exe|dll|com|net|org|ru/iu;

async function urlHits(limit = 20) {
  const r = await fetch(
    `${BASE}/search?content_type=accessibility&start_time=${WINDOW_MIN}m%20ago&end_time=now` +
      `&limit=${limit}&max_content_length=4000&format=json` +
      `&fields=content.frame_id,content.timestamp,content.app_name,content.window_name,content.text`,
  );
  if (!r.ok) return [];
  const j = await r.json();
  const out = [];
  for (const row of j?.data ?? []) {
    const c = row?.content ?? {};
    const text = String(c.text ?? "");
    if (!text) continue;
    const seen = new Set();
    for (const m of text.matchAll(URL_RE)) {
      let host = m[1].replace(/^https?:\/\//i, "").split(/[/?#]/)[0].toLowerCase();
      host = host.replace(/^www\./, "");
      if (NOISE.test(host)) continue;
      if (host.length < 4 || !host.includes(".")) continue;
      if (seen.has(host)) continue;
      seen.add(host);
      out.push({
        host,
        url: m[1].startsWith("http") ? m[1] : `https://${m[1]}`,
        ts: c.timestamp ?? null,
        app: c.app_name ?? "",
        window: c.window_name ?? "",
      });
    }
  }
  return out;
}

const main = async () => {
  const since = `-${WINDOW_MIN} minutes`;
  const h = await health();

  const [frames, switches, clicks, uiAll, urls] = await Promise.all([
    sql(
      `SELECT timestamp, app_name, window_name, browser_url, focused FROM frames
       WHERE datetime(timestamp) > datetime('now','${WINDOW_MIN} minutes')
       ORDER BY timestamp ASC LIMIT 5000`,
    ),
    sql(
      `SELECT timestamp, app_name, window_title FROM ui_events
