    ),
    sql(
      `SELECT event_type, COUNT(*) AS n FROM ui_events
       WHERE datetime(timestamp) > datetime('now','${WINDOW_MIN} minutes')
       GROUP BY event_type ORDER BY n DESC LIMIT 20`,
    ),
    urlHits(),
  ]);

  const payload = {
